function rootGraph(){let ir=clone(S.ir);for(let i=S.modulePath.length-1;i>=0;i--){const f=S.modulePath[i],parent=clone(f.ir),node=parent.nodes.find(n=>n.id===f.id);node.module=ir;ir=parent;}return ir;}
save=async function(){const ir=rootGraph(),positions=S.modulePath.length?S.modulePath[0].positions:S.positions;const p=await api('/projects/'+S.project.id,'PUT',{name:S.project.name,ir,dataset_id:S.project.dataset_id,layout:positions,search_space:S.space});S.project=p;S.projects=S.projects.map(x=>x.id===p.id?p:x);saved();const revision=$('.studio-title p');if(revision)revision.textContent=(S.modulePath.length?'Module editor':'Architecture Studio')+' · '+S.ir.nodes.length+' blocks · v'+p.revision;toast('Saved as version '+p.revision);};
