opIcon=function(op){let path=family(op)==='attention'?'M4 5h16v14H4zM8 9h8M8 12h8M8 15h4M1 9h3M20 15h3':family(op)==='vision'?'M5 3h14v4H5zM3 10h18v4H3zM5 17h14v4H5z':op==='Input'?'M6 3h12v18H6zM9 7h6M9 11h6M9 15h3':op==='Add'?'M5 12h14M12 5v14':op==='Embedding'||op.includes('Position')?'M3 5h4v14H3zM10 3h4v18h-4zM17 7h4v10h-4z':'M4 6h6v5H4zM14 13h6v5h-6zM10 8h7v5';return `<span class="op-icon ${family(op)}"><svg viewBox="0 0 24 24"><path d="${path}"/></svg></span>`;};
