function updateSelectionToolbar(){let bar=$('.selection-toolbar');if(S.selection.length>1){if(!bar){bar=document.createElement('div');bar.className='selection-toolbar';$('#canvas').append(bar)}bar.innerHTML=`${S.selection.length} nodes selected <button class="mini-button" data-action="pack-module">Create module</button>`;bindAction($('[data-action]',bar));}else bar?.remove();}
const oldBindCanvas=bindCanvas;
bindCanvas=function(){oldBindCanvas();const c=$('#canvas'),old=c.onpointerdown;c.onpointerdown=e=>{if(!e.shiftKey||e.target.closest('.node,.canvas-controls,.selection-toolbar'))return old(e);e.preventDefault();const b=c.getBoundingClientRect(),start={x:e.clientX-b.left,y:e.clientY-b.top};const box=document.createElement('div');box.className='selection-box';c.append(box);c.setPointerCapture(e.pointerId);c.onpointermove=ev=>{const end={x:ev.clientX-b.left,y:ev.clientY-b.top},x=Math.min(start.x,end.x),y=Math.min(start.y,end.y),w=Math.abs(end.x-start.x),h=Math.abs(end.y-start.y);Object.assign(box.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});S.selection=Object.entries(S.positions).filter(([id,p])=>id!=='input'&&p.x*S.zoom+S.pan.x<x+w&&(p.x+210)*S.zoom+S.pan.x>x&&p.y*S.zoom+S.pan.y<y+h&&(p.y+96)*S.zoom+S.pan.y>y).map(([id])=>id);$$('[data-node]').forEach(n=>n.classList.toggle('selected',S.selection.includes(n.dataset.node)));};c.onpointerup=()=>{box.remove();c.onpointermove=null;S.selected=S.selection[0]||S.selected;renderInspector();updateSelectionToolbar();};};c.oncontextmenu=e=>{e.preventDefault();contextMenu(e.clientX,e.clientY)};};
function contextMenu(x,y){$('.context-menu')?.remove();const el=document.createElement('div');el.className='context-menu';el.style.left=Math.min(x,innerWidth-210)+'px';el.style.top=Math.min(y,innerHeight-170)+'px';el.innerHTML=`<button data-action="pack-module">${icon('layers')}Create Module</button><button data-action="pack-module">${icon('save')}Save as Reusable Block</button><button data-action="select-all">${icon('graph')}Select All Nodes</button>`;document.body.append(el);$$('[data-action]',el).forEach(b=>{bindAction(b);const fn=b.onclick;b.onclick=e=>{el.remove();fn(e)}});setTimeout(()=>document.addEventListener('pointerdown',e=>{if(!el.contains(e.target))el.remove()},{once:true}),0);}
function pruneSpace(){const paths=new Set();function visit(ir,prefix=''){for(const n of ir.nodes){paths.add(prefix+n.id);if(n.op==='Module')visit(n.module,prefix+n.id+'/')}}visit(rootGraph());S.space.variables=S.space.variables.filter(v=>paths.has(v.node_id));const ids=new Set(S.space.variables.map(v=>v.id));for(const v of S.space.variables)if(v.conditional_dependencies&&!ids.has(v.conditional_dependencies.variable))delete v.conditional_dependencies;}
async function changedGraph(){pruneSpace();setDirty();await analyze(false);render();}
addNode=async function(op,pos){history();const after=S.selected&&S.ir.nodes.some(n=>n.id===S.selected)?S.selected:'input';let base=op.toLowerCase(),i=1;while(S.ir.nodes.some(n=>n.id===base+i))i++;const id=base+i,config=clone(DEFAULTS[op]||{});if(op==='Linear')config.out_features=dataset()?.classes.length||3;const n={id,op,inputs:[after],config};S.ir.nodes.forEach(x=>x.inputs=x.inputs.map(v=>v===after?id:v));if(S.ir.output===after)S.ir.output=id;S.ir.nodes.splice(S.ir.nodes.findIndex(n=>n.id===after)+1,0,n);S.selected=id;S.selection=[id];if(pos)S.positions[id]=pos;else S.positions={};await changedGraph();};
function configField(key,value){if(typeof value==='boolean')return `<label class="field"><span>${key}</span><select name="${key}" data-value-type="boolean"><option value="true" ${value?'selected':''}>true</option><option value="false" ${!value?'selected':''}>false</option></select></label>`;if(ENUMS[key])return `<label class="field"><span>${key}</span><select name="${key}" data-value-type="string">${ENUMS[key].map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select></label>`;return field(key,key,value,typeof value==='number'?'number':'text',typeof value==='number'?'step="any"':'');}
renderInspector=function(){if(!$('#inspector'))return;const n=S.ir.nodes.find(n=>n.id===S.selected),spec=S.analysis?.nodes.find(n=>n.id===S.selected);if(!n){$('#inspector').innerHTML=`<div class="section-title">INPUT TENSOR</div><div class="inspector-heading">${opIcon('Input')}<div><h3>${S.ir.input_type==='tokens'?'Token Input':'Image Input'}</h3><p>${S.ir.input_shape.join(' × ')}</p></div></div><p class="field-note">Select a node to edit parameters or define search variables.</p>${btn('Choose template','template','plus')}`;return;}
$('#inspector').innerHTML=`<div class="inspector-heading">${opIcon(n.op)}<div><h3>${esc(n.name||OP_NAMES[n.op]||n.op)}</h3><p>${esc(n.id)}${n.op==='Module'?' · '+n.module.nodes.length+' internal blocks':''}</p></div></div><div class="inspector-tabs"><button data-inspector-tab="properties" class="${S.inspectorTab==='properties'?'active':''}">Properties</button><button data-inspector-tab="search" class="${S.inspectorTab==='search'?'active':''}">Search Space ${visibleVariables(n.id).length?`(${visibleVariables(n.id).length})`:''}</button></div>${S.inspectorTab==='search'?searchInspector(n):`<form id="node-form"><label class="field"><span>Name</span><input name="_name" value="${esc(n.name||OP_NAMES[n.op]||n.op)}" maxlength="80"></label><div class="node-form-grid">${Object.entries(n.config).map(([k,v])=>configField(k,v)).join('')}</div><label class="field"><span>Inputs</span><input name="_inputs" value="${esc(n.inputs.join(', '))}"></label><label class="field"><span>Stage Group</span><input name="_stage" value="${esc(n.stage||'')}" maxlength="60" placeholder="Optional stage name"></label><label class="field"><span>Diagram annotation</span><input name="_annotation" value="${esc(n.annotation||'')}" maxlength="100" placeholder="Optional"></label><button type="submit" class="btn small full-width">Apply changes</button></form>${n.op==='Module'?`<div class="section-gap">${btn('Enter module','enter-selected-module','layers')}${btn('Save module version','save-module-version','save')}</div>`:''}<div class="section-title" style="margin-top:25px">TENSOR</div><div class="inspector-kv"><span>Input</span><code>${spec?.input_shapes.map(s=>s.join('×')).join(' / ')||'—'}</code></div><div class="inspector-kv"><span>Output</span><code>${spec?.shape.join('×')||'—'}</code></div><div class="inspector-kv"><span>Parameters</span><code>${spec?fmt(spec.params):'—'}</code></div><div class="inspector-kv"><span>MACs</span><code>${spec?compact(spec.macs):'—'}</code></div><div class="actions section-gap">${btn('Set as output','set-output','arrow')}${btn('Delete','delete-node','trash')}</div>`}`;
$$('[data-inspector-tab]').forEach(b=>b.onclick=()=>{S.inspectorTab=b.dataset.inspectorTab;renderInspector()});$('#node-form')?.addEventListener('submit',fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget);history();n.name=f.get('_name');n.annotation=f.get('_annotation');n.stage=f.get('_stage');for(const [k,v] of Object.entries(n.config))n.config[k]=typeof v==='number'?Number(f.get(k)):typeof v==='boolean'?f.get(k)==='true':f.get(k);n.inputs=String(f.get('_inputs')).split(',').map(v=>v.trim()).filter(Boolean);await changedGraph()}));$$('[data-variable-edit]').forEach(b=>b.onclick=()=>variableModal(n,S.space.variables.find(v=>v.id===b.dataset.variableEdit)));$$('[data-variable-delete]').forEach(b=>b.onclick=()=>{history();S.space.variables=S.space.variables.filter(v=>v.id!==b.dataset.variableDelete);setDirty();render()});$$('[data-state]').forEach(b=>b.onclick=()=>{history();S.space.nodes[nodePath(n.id)]={state:b.dataset.state};setDirty();render()});$$('[data-action]',$('#inspector')).forEach(bindAction);};
function searchInspector(n){const state=S.space.nodes[nodePath(n.id)]?.state|| (visibleVariables(n.id).length?'Searchable':'Fixed'),vs=S.space.variables.filter(v=>v.node_id===nodePath(n.id));return `<div class="section-title">SEARCHABILITY</div><div class="search-state-picker">${['Fixed','Searchable','Conditional'].map(k=>`<button data-state="${k}" class="${state===k?'active':''}">${k}</button>`).join('')}</div>${vs.map(v=>`<div class="variable-card"><strong>${esc(v.target)}</strong><small>${esc(v.kind==='range'?`${v.numeric_range.min} → ${v.numeric_range.max} / step ${v.numeric_range.step}`:JSON.stringify(v.candidate_values||[false,true]))}${v.conditional_dependencies?'<br>When '+esc(v.conditional_dependencies.variable)+' '+esc(v.conditional_dependencies.operator)+' '+esc(JSON.stringify(v.conditional_dependencies.value)):''}</small><div class="actions"><button class="mini-button" data-variable-edit="${v.id}">Edit</button><button class="mini-button" data-variable-delete="${v.id}">Remove</button></div></div>`).join('')}<button class="btn small full-width" data-action="add-variable">${icon('plus')}Add search variable</button><div class="section-title" style="margin-top:25px">SPACE ESTIMATE</div><div class="inspector-kv"><span>Node combination bound</span><code>${fmt(vs.reduce((p,v)=>p*variableSize(v),1),0)}</code></div><div class="inspector-kv"><span>Graph search variables</span><code>${S.space.variables.length}</code></div><button class="link-button section-gap" data-action="space-summary">View search space summary →</button>`;}
function variableSize(v){if(v.kind==='boolean')return 2;if(v.kind==='range'){const r=v.numeric_range;return v.sampling==='log'?r.samples||5:Math.floor((r.max-r.min)/r.step)+1}return v.candidate_values?.length||1;}
function parseScalar(v){try{return JSON.parse(v)}catch{return v}}
function variableModal(n,v=null){const targets=[...Object.keys(n.config).map(k=>'config.'+k),'repeat','enabled','op',...(n.op==='Module'?['module']:[])];modal(v?'Edit search variable':'Add search variable',`<form id="variable-form"><div class="form-grid"><label class="field"><span>Parameter / structure</span><select name="target">${targets.map(k=>`<option ${v?.target===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field"><span>Domain type</span><select name="kind"><option value="discrete" ${v?.kind==='discrete'?'selected':''}>Discrete choices</option><option value="range" ${v?.kind==='range'?'selected':''}>Numeric range</option><option value="boolean" ${v?.kind==='boolean'?'selected':''}>Boolean switch</option></select></label></div><label class="field" id="candidate-values-field"><span>Candidate values (comma-separated or JSON array)</span><input name="values" value="${esc(JSON.stringify(v?.candidate_values||defaultCandidateValues(n,targets[0])))}" placeholder="Example: [32,64,128]"></label><div id="module-choice-fields" class="select-chips">${S.modules.map(m=>`<label class="chip"><input type="checkbox" name="module_choices" value="${m.id}" ${v?.candidate_values?.includes(m.id)?'checked':''}>${esc(m.name)} · v${m.version}</label>`).join('')}</div><div id="range-fields" class="form-grid">${field('Min','min',v?.numeric_range?.min??1,'number','step="any"')}${field('Max','max',v?.numeric_range?.max??4,'number','step="any"')}${field('Step','step',v?.numeric_range?.step??1,'number','step="any"')}<label class="field"><span>Sampling</span><select name="sampling"><option value="linear">Linear</option><option value="log" ${v?.sampling==='log'?'selected':''}>Logarithmic (5 samples)</option></select></label><label class="field"><span>Value type</span><select name="value_type"><option value="integer">Integer</option><option value="float" ${v?.value_type==='float'?'selected':''}>Float</option></select></label></div><div class="section-title section-gap">CONDITION · OPTIONAL</div><div class="form-grid"><label class="field"><span>Depends on variable</span><select name="dependency"><option value="">Always participates</option>${S.space.variables.filter(x=>x.id!==v?.id).map(x=>`<option value="${x.id}" ${v?.conditional_dependencies?.variable===x.id?'selected':''}>${esc(x.node_id+' / '+x.target)}</option>`).join('')}</select></label><label class="field"><span>Conditional value (enabled when equal)</span><input name="condition" value="${esc(JSON.stringify(v?.conditional_dependencies?.value??true))}"></label></div><label class="field"><span>Default value (optional)</span><input name="default" value="${esc(v?.default==null?'':JSON.stringify(v.default))}"></label><div class="actions"><button class="btn primary" type="submit">Save variable</button><span class="field-note">Only this node is searchable; other structures stay fixed.</span></div></form>`);const f=$('#variable-form');function toggle(){const kind=f.elements.kind.value;$('#range-fields').style.display=kind==='range'?'grid':'none';$('#candidate-values-field').style.display=kind==='discrete'&&f.elements.target.value!=='module'?'block':'none';$('#module-choice-fields').style.display=f.elements.target.value==='module'?'flex':'none'}f.elements.kind.onchange=toggle;f.elements.target.onchange=()=>{toggle();if(!v)f.elements.values.value=JSON.stringify(defaultCandidateValues(n,f.elements.target.value))};toggle();f.onsubmit=fire(async e=>{e.preventDefault();const d=new FormData(f),target=d.get('target'),kind=d.get('kind');let candidates=[];if(target==='module'){candidates=d.getAll('module_choices')}else if(kind==='discrete'){const text=d.get('values').trim();candidates=text.startsWith('[')?JSON.parse(text):text.split(',').map(x=>parseScalar(x.trim()));}const variable={id:v?.id||('v_'+n.id+'_'+target.replaceAll('.','_')+'_'+Math.random().toString(36).slice(2,5)),node_id:nodePath(n.id),target,kind,candidate_values:candidates,numeric_range:{min:Number(d.get('min')),max:Number(d.get('max')),step:Number(d.get('step')),samples:5},sampling:d.get('sampling'),value_type:d.get('value_type')};if(d.get('dependency'))variable.conditional_dependencies={variable:d.get('dependency'),operator:'eq',value:parseScalar(d.get('condition'))};if(d.get('default').trim())variable.default=parseScalar(d.get('default'));const next=clone(S.space);if(target==='module')next.module_choices=Object.fromEntries(S.modules.map(m=>[m.id,clone(m.node)]));next.variables=v?next.variables.map(x=>x.id===v.id?variable:x):[...next.variables,variable];next.nodes[nodePath(n.id)]={state:variable.conditional_dependencies?'Conditional':'Searchable'};await api('/search-space/summary','POST',{ir:rootGraph(),search_space:next});history();S.space=next;S.mode='search';S.inspectorTab='search';setDirty();$('#modal').close();render()});}
function defaultCandidateValues(n,target){const key=target.replace('config.',''),val=n.config[key];if(target==='module')return S.modules.slice(0,2).map(m=>m.id);if(target==='enabled')return [true,false];if(target==='repeat')return [1,2,3];if(target==='op')return n.op.includes('Pool')?['MaxPool2d','AvgPool2d','Identity']:['Conv2d','ConvBlock','ResidualBlock'];if(ENUMS[key])return ENUMS[key];if(typeof val==='boolean')return [false,true];if(['dropout','p','attn_dropout','proj_dropout'].includes(key))return [0,.1,.2];if(key==='num_heads')return [2,4,8];if(key==='kernel_size')return [3,5,7];if(key==='stride')return [1,2];if(key==='depth')return [1,2,4];if(key==='patch_size')return [4,8];if(typeof val==='number')return [...new Set([Math.max(1,Math.round(val/2)),val,Math.round(val*2)])];return [val];}

async function packageModal(){const ids=S.selection.filter(id=>S.ir.nodes.some(n=>n.id===id));if(!ids.length&&S.selected&&S.selected!=='input')ids.push(S.selected);if(!ids.length)throw Error('Shift-click nodes or Shift-drag to select a subgraph first');const nodes=S.ir.nodes.filter(n=>ids.includes(n.id));const choices=nodes.flatMap(n=>Object.entries(n.config).map(([key,value])=>({node:n.id,key,value})));modal('Create reusable module',`<form id="package-form"><p>Package  ${ids.length}  nodes into a module. Boundary inputs and outputs are detected automatically.</p><div class="form-grid">${field('Module name','name','My Block','text','required maxlength="80"')}${field('Category','category','My Blocks','text','maxlength="80"')}</div><label class="field"><span>Description</span><input name="description" maxlength="200" placeholder="What does this module do?"></label><div class="section-title section-gap">EXPOSE PARAMETERS</div><p class="field-note">Expose selected parameters for external editing and search.</p><div class="select-chips">${choices.map((c,i)=>`<label class="chip"><input type="checkbox" name="exposed" value="${i}">${esc(c.node+'.'+c.key)}</label>`).join('')}</div><button class="btn primary" type="submit">${icon('layers')}Package & save to library</button></form>`);$('#package-form').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget),bindings={};for(const idx of f.getAll('exposed')){const c=choices[Number(idx)],name=c.node+'_'+c.key;bindings[name]=[{node:c.node,parameter:c.key}]}history();const r=await api('/modules/package','POST',{ir:S.ir,selected:ids,name:f.get('name'),category:f.get('category'),description:f.get('description'),bindings,source_project:S.project.id});S.ir=r.ir;const node=S.ir.nodes.find(n=>n.id===r.node.id);node.library_id=r.module.id;S.modules=await api('/modules');S.space.variables=S.space.variables.map(v=>{for(const oldId of ids){const path=nodePath(oldId);if(v.node_id===path||v.node_id.startsWith(path+'/'))v.node_id=nodePath(node.id)+'/'+v.node_id.slice((S.modulePath.map(f=>f.id).join('/')+(S.modulePath.length?'/':'')).length);}return v});S.selection=[node.id];S.selected=node.id;S.positions={};$('#modal').close();await changedGraph();toast('Module saved for reuse across projects')});}
async function enterModule(id){const n=S.ir.nodes.find(n=>n.id===id);if(n?.op!=='Module')return;S.modulePath.push({ir:S.ir,id,name:n.name||'Module',positions:S.positions,selected:S.selected,zoom:S.zoom,pan:{...S.pan}});S.ir=clone(n.module);S.ir.name=n.name;S.positions=clone(n.module_layout||{});S.selection=[];S.selected=S.ir.nodes[0]?.id;S.history=[];S.future=[];S.pan={x:25,y:20};S.zoom=.8;S.inspectorTab='properties';await analyze(false);render();setTimeout(()=>ACTIONS.fit(),20);}
async function exitModule(level=S.modulePath.length-1){while(S.modulePath.length>level){const f=S.modulePath.pop(),n=f.ir.nodes.find(n=>n.id===f.id);n.module=S.ir;n.module_layout=S.positions;for(const [name,targets] of Object.entries(n.bindings||{})){const t=targets[0],inner=S.ir.nodes.find(v=>v.id===t.node);if(inner)n.config[name]=inner.config[t.parameter];}S.ir=f.ir;S.positions=f.positions;S.selected=n.id;S.zoom=f.zoom||.8;S.pan=f.pan||{x:25,y:20};}S.selection=[S.selected];setDirty();await analyze(false);render();}
async function insertModule(id){const m=S.modules.find(m=>m.id===id);if(!m)throw Error('Module not found');const after=S.selected&&S.ir.nodes.some(n=>n.id===S.selected)?S.selected:'input',n=clone(m.node);history();let ident='module_'+id.slice(0,7),i=1;while(S.ir.nodes.some(n=>n.id===ident))ident='module_'+id.slice(0,7)+'_'+i++;n.id=ident;n.inputs=[after,...S.selection.filter(x=>x!==after)];const portCount=n.module.input_ports?.length||1;n.inputs=n.inputs.slice(0,portCount);while(n.inputs.length<portCount)n.inputs.push(after);n.library_id=id;S.ir.nodes.forEach(x=>x.inputs=x.inputs.map(v=>v===after?ident:v));if(S.ir.output===after)S.ir.output=ident;S.ir.nodes.push(n);S.selected=ident;S.selection=[ident];S.positions={};await api('/modules/'+id+'/used','POST');navigate('architecture');await changedGraph();}
function modulePicture(m){const purple=m.category?.includes('Transformer'),c=purple?'#d8cee9':'#ccdfe0';return `<svg viewBox="0 0 180 110" fill="none"><path d="M22 79 82 43l74 14-60 36Z" fill="#eaf0f2"/><path d="M38 66V52l52-29 51 14v17L88 83Z" fill="${c}" stroke="#fff"/><path d="M38 52 90 23l51 14-53 30Z" fill="${purple?'#ede6f9':'#e4eff0'}" stroke="#fff"/><path d="m88 67 53-30v17L88 83Z" fill="${purple?'#c4b4dd':'#bad2d4'}"/><path d="M50 44 99 17l41 11M49 36 98 10l41 11" stroke="${purple?'#d4c8e6':'#d2e3e4'}" stroke-width="2"/><path d="M71 48 91 37l20 6-19 11Z" stroke="${purple?'#b8a2d2':'#a0c1c5'}"/><circle cx="27" cy="85" r="3" fill="#c2d5ce"/><path d="m28 85 20-11m95-23 17-10" stroke="#c6d6d7"/></svg>`;}
function renderModules(){const category=S.moduleCategory,query=S.moduleQuery||'';const list=S.modules.filter(m=>(category==='all'||category==='favorites'&&m.favorite||category==='recent'&&m.last_used||m.category===category)&&m.name.toLowerCase().includes(query.toLowerCase()));$('#page').innerHTML=heading('YOUR BUILDING BLOCKS','Module Library','Start your next architecture with a reusable block.',btn('Import module','import-module','upload')+btn('Back to designer','go-architecture','graph',true))+`<div class="page-content"><div class="catalog-bar"><input id="module-search" placeholder="Find modules…" value="${esc(query)}" aria-label="Find modules">${[['all','All'],['favorites','Favorites'],['recent','Recently used'],...new Set(S.modules.map(m=>m.category||'My Blocks'))].map(x=>Array.isArray(x)?x:[x,x]).map(([id,title])=>`<button class="catalog-tab ${id===category?'active':''}" data-category="${esc(id)}">${esc(title)}</button>`).join('')}</div><div class="module-card-grid">${list.map(m=>`<article class="module-card"><div class="module-preview">${modulePicture(m)}<button class="card-favorite ${m.favorite?'active':''}" data-favorite="${m.id}" aria-label="Favorites ${esc(m.name)}">${m.favorite?'★':'☆'}</button></div><div class="module-card-content"><h3>${esc(m.name)}</h3><span class="badge purple">${esc(m.category)} · v${m.version}</span><p>${esc(m.description||'Reusable architecture block')}</p><div class="module-meta"><span>${m.internal_nodes} blocks</span><span>${compact(m.params)} parameters</span></div><div class="module-meta"><span>${(m.input_ports||[]).map(p=>p.shape.join('×')).join(' / ')} → ${m.output_shape?.join('×')}</span></div><div class="actions"><button class="btn small" data-module-info="${m.id}">Details</button><button class="btn small primary" data-insert-module="${m.id}">${icon('plus')}Insert on canvas</button></div></div></article>`).join('')}</div>${!list.length?empty('Create your first module','Select nodes on the canvas and right-click Create Module to save one here.'):''}</div>`;$$('[data-category]').forEach(b=>b.onclick=()=>{S.moduleCategory=b.dataset.category;render()});$('#module-search').oninput=e=>{S.moduleQuery=e.target.value;clearTimeout(S.moduleSearchTimer);S.moduleSearchTimer=setTimeout(()=>{const start=e.target.selectionStart;render();$('#module-search').focus();$('#module-search').setSelectionRange(start,start)},250)};$$('[data-favorite]').forEach(b=>b.onclick=fire(async()=>{await api('/modules/'+b.dataset.favorite+'/favorite','POST');S.modules=await api('/modules');render()}));$$('[data-insert-module]').forEach(b=>b.onclick=fire(()=>insertModule(b.dataset.insertModule)));$$('[data-module-info]').forEach(b=>b.onclick=()=>{const m=S.modules.find(m=>m.id===b.dataset.moduleInfo);modal(m.name,`${modulePicture(m)}<p>${esc(m.description)}</p><div class="connected-ports">Inputs: ${(m.input_ports||[]).map(p=>esc(p.id+' ['+p.shape.join(', ')+']')).join('<br>')}<br>Output: ${m.output_shape?.join(' × ')}</div><pre class="settings-code">${esc(JSON.stringify(m.parameter_schema,null,2))}</pre><p class="field-note">${esc(m.compatibility)} · ${m.created_at?new Date(m.created_at*1000).toLocaleDateString():''}</p><button class="btn" id="download-module">${icon('download')}Export module JSON</button>`);$('#download-module').onclick=()=>download(JSON.stringify(m,null,2),m.name+'.json','application/json')});}
async function useTemplate(kind){const d=S.datasets.find(d=>d.id===S.project.dataset_id)||dataset();let target=d;if(kind==='transformer')target=S.datasets.find(x=>x.input_type==='tokens')||d;else if(d.input_type==='tokens')target=S.datasets.find(x=>!x.input_type)||d;const ir=await api(`/templates/${kind}?classes=${target.classes.length}&size=${target.shape.length===3?target.shape[1]:32}`);history();S.ir=ir;S.project.dataset_id=target.id;S.dataset=target.id;S.positions={};S.modulePath=[];S.selection=[];S.selected=ir.nodes[0].id;S.space={schema_version:1,variables:[],nodes:{},global_constraints:{},local_constraints:[]};S.mode='design';S.inspectorTab='properties';S.pan={x:25,y:20};S.zoom=.8;await changedGraph();$('#modal').close();navigate('architecture');setTimeout(()=>ACTIONS.fit(),30);}
templateModal=function(){modal('Start with a template',`<p>Choose a starting point; every structure remains editable and searchable.</p><div class="template-grid">${[['residual','Residual CNN','Residual features and classification head'],['cnn','Convolutional Network','Lightweight CNN for fast exploration'],['vit','Vision Transformer','Patch embedding、Encoder、MLP Head'],['transformer','Transformer Encoder','Token embedding、Position encoding and classification']].map(([id,name,desc])=>`<button class="template-card" data-template="${id}">${opIcon(id==='vit'?'TransformerStack':id==='transformer'?'Embedding':'ResidualBlock')}<strong>${name}</strong><small>${desc}</small></button>`).join('')}</div>`);$$('[data-template]',$('#modal')).forEach(b=>b.onclick=fire(()=>useTemplate(b.dataset.template)));};

function diagramFields(){const o=S.exportOptions;return `<div class="section-title">${S.exportMode==='3d'?'SCENE SETTINGS':'DIAGRAM SETTINGS'}</div>${S.exportMode==='2d'?`<label class="field"><span>Style</span><select name="style">${[['clean','Clean Paper'],['minimal','Minimal Academic'],['color','Color-Coded Blocks'],['mono','Monochrome Publication'],['poster','Conference Poster']].map(([v,l])=>`<option value="${v}" ${o.style===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Orientation</span><select name="orientation"><option value="horizontal" ${o.orientation==='horizontal'?'selected':''}>Left to right</option><option value="vertical" ${o.orientation==='vertical'?'selected':''}>Top to bottom</option></select></label><div class="form-grid">${field('Font size','font_size',o.font_size,'number','min="9" max="18"')}${field('Line width','line_width',o.line_width,'number','min="0.5" max="4" step="0.5"')}</div><label class="field"><span>Paper size</span><select name="paper_size">${[['auto','Fit architecture'],['a4','A4 landscape'],['letter','Letter'],['poster','A2 poster']].map(([v,l])=>`<option value="${v}" ${o.paper_size===v?'selected':''}>${l}</option>`).join('')}</select></label>`:`<label class="field"><span>Theme</span><select name="theme">${[['product','Modern Product'],['white','White Minimal 3D'],['dark','Dark Tech Showcase'],['cover','Publication Cover'],['investor','Investor Deck']].map(([v,l])=>`<option value="${v}" ${o.theme===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="form-grid">${field('Camera angle','camera_angle',o.camera_angle,'number','min="5" max="60"')}${field('Depth','depth',o.depth,'number','min="4" max="50"')}${field('Shadow','shadow',o.shadow,'number','min="0" max="1" step="0.1"')}<label class="field"><span>Layout</span><select name="layout"><option value="compact" ${o.layout==='compact'?'selected':''}>Compact</option><option value="cinematic" ${o.layout==='cinematic'?'selected':''}>Cinematic</option></select></label></div>`}${field('Title','title',o.title||S.ir.name||'Architecture','text','maxlength="120"')}${field('Subtitle','subtitle',o.subtitle||'','text','maxlength="180"')}<label class="field"><span>PNG resolution</span><select name="resolution">${[1600,2400,3840,4800].map(v=>`<option ${o.resolution===v?'selected':''}>${v}</option>`).join('')}</select></label>${['show_shapes','show_params','show_labels','color_coding','legend'].filter(k=>S.exportMode==='2d'||['show_shapes','show_params'].includes(k)).map(k=>`<label class="checkbox-field"><input type="checkbox" name="${k}" ${o[k]?'checked':''}>${{show_shapes:'Tensor shapes',show_params:'Parameter counts',show_labels:'Module labels',color_coding:'Color coding',legend:'Figure legend'}[k]}</label>`).join('')}<button class="btn small full-width" type="submit">Update preview</button>`;}
function renderExportStudio(){$('#page').innerHTML=heading('MADE TO BE SHARED','Export Studio','Create paper diagrams and spatial visuals from your real architecture.',btn('Back to designer','go-architecture','graph'))+`<div class="page-content"><div class="export-mode-tabs"><button data-export-mode="2d" class="${S.exportMode==='2d'?'active':''}">2D Paper Diagram</button><button data-export-mode="3d" class="${S.exportMode==='3d'?'active':''}">3D Architecture Visual</button></div><div class="export-layout"><div><div class="export-preview" id="export-preview"><span class="preview-loading">Generating architecture diagram…</span></div><div class="export-caption"><span>Architecture-driven · Auto layout</span><span>${S.exportMode==='2d'?'Editable vector / High-resolution raster':'Spatial card renderer / High-resolution export'}</span></div><div class="actions section-gap">${btn('Download SVG','download-svg','download')}${btn('Download PNG','download-png','download',true)}${btn('Download PDF','download-pdf','download')}</div></div><form class="export-controls" id="export-form">${diagramFields()}</form></div></div>`;$$('[data-export-mode]').forEach(b=>b.onclick=()=>{S.exportMode=b.dataset.exportMode;render()});$('#export-form').onsubmit=fire(async e=>{e.preventDefault();readExportOptions();await previewDiagram()});$('#export-form').onchange=()=>{readExportOptions();clearTimeout(S.exportTimer);S.exportTimer=setTimeout(()=>fire(previewDiagram)(),350)};previewDiagram().catch(e=>{if($('#export-preview'))$('#export-preview').textContent=e.message});}
function readExportOptions(){const f=$('#export-form');if(!f)return;const o=S.exportOptions;for(const e of f.elements){if(!e.name)continue;o[e.name]=e.type==='checkbox'?e.checked:e.type==='number'||e.name==='resolution'?Number(e.value):e.value;}}
async function previewDiagram(){const token=Date.now();S.previewToken=token;const r=await fetch('/api/diagrams',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ir:S.ir,...S.exportOptions,mode:S.exportMode,format:'svg'})});if(!r.ok)throw Error((await r.json()).detail);const svg=await r.text();if(S.previewToken===token&&$('#export-preview'))$('#export-preview').innerHTML=svg;}
async function downloadDiagram(format){readExportOptions();toast('Generating '+format.toUpperCase()+'…');const r=await fetch('/api/diagrams',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ir:S.ir,...S.exportOptions,mode:S.exportMode,format})});if(!r.ok)throw Error((await r.json()).detail);const blob=await r.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=(S.ir.name||'architecture')+'-'+S.exportMode+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Architecture diagram generated');}

async function spaceSummary(){const r=await api('/search-space/summary','POST',{ir:rootGraph(),search_space:S.space});modal('Search Space Summary',`<div class="summary-grid">${[['Search variables',r.variables],['Combination bound',compact(r.combinations)],['Legal candidates'+(r.estimate?' · Estimated':''),compact(r.legal_combinations)],['Conditional variables',r.conditional_variables],['Fixed nodes',r.fixed_nodes],['Searchable nodes',r.searchable_nodes]].map(([k,v])=>`<div class="summary-stat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="connected-ports">${r.estimate?`Sampled  ${r.checked}  combinations to estimate the filtered space.`:`Checked all  ${r.checked}  combinations.`} Start with  ${r.recommended_candidates}  candidates.</div>${Object.keys(r.rejections).length?`<details><summary class="field-note">View filtering reasons</summary>${Object.entries(r.rejections).map(([k,v])=>`<p class="field-note">${esc(k)} × ${v}</p>`).join('')}</details>`:''}<div class="actions section-gap"><button class="btn" id="summary-config">Configure constraints</button><button class="btn primary" id="summary-search">Open Search Lab</button></div>`);$('#summary-config').onclick=()=>constraintsModal();$('#summary-search').onclick=()=>{$('#modal').close();navigate('search')};}
function constraintsModal(){const c=S.space.global_constraints||{};modal('Search constraints',`<form id="constraints-form"><div class="form-grid">${field('Parameter limit (M)','max_params',(c.max_params||1e6)/1e6,'number','min="0.001" max="50" step="any"')}${field('MACs Limit (M)','max_macs',(c.max_macs||100e6)/1e6,'number','min="0.001" max="10000" step="any"')}${field('Layer limit','max_layers',c.max_layers||200,'number','min="1" max="2048"')}${field('Static memory budget (MB)','max_memory_mb',c.max_memory_mb||256,'number','min="1" max="32768"')}${field('Latency target (ms，Reserved)','latency_ms',c.latency_ms||10,'number','min="0.1" step="any"')}</div><div class="form-grid">${field('Input shape（optional JSON)','input_shape',c.input_shape?JSON.stringify(c.input_shape):'','text')}${field('Output shape（optional JSON)','output_shape',c.output_shape?JSON.stringify(c.output_shape):'','text')}</div><div class="section-title section-gap">RELATIONSHIPS</div><div id="relationship-list">${(S.space.local_constraints||[]).map((rule,i)=>`<div class="variable-card"><strong>${esc(rule.left)} ${esc(rule.operator)} ${esc(rule.right)}</strong><button class="mini-button" type="button" data-remove-rule="${i}">Remove</button></div>`).join('')}</div><div class="form-grid"><label class="field"><span>Left parameter / variable</span><select name="left"><option value="">None</option>${S.ir.nodes.flatMap(n=>Object.keys(n.config).filter(k=>typeof n.config[k]==='number').map(k=>`<option>${n.id}.${k}</option>`)).join('')}${S.space.variables.map(v=>`<option value="$${v.id}">${esc(v.node_id+' / '+v.target)}</option>`).join('')}</select></label><label class="field"><span>Relation</span><select name="operator"><option value="divisible_by">Divisible by</option><option value="eq">Equal to</option><option value="le">Less than or equal to</option><option value="ge">Greater than or equal to</option></select></label>${field('Right value / node.parameter / $variable','right','4','text')}</div><button class="btn primary" type="submit">Save constraints</button></form>`);const removed=new Set();$$('[data-remove-rule]').forEach(b=>b.onclick=()=>{removed.add(Number(b.dataset.removeRule));b.closest('.variable-card').remove()});$('#constraints-form').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget),constraints={max_params:Math.round(Number(f.get('max_params'))*1e6),max_macs:Math.round(Number(f.get('max_macs'))*1e6),max_layers:Number(f.get('max_layers')),max_memory_mb:Number(f.get('max_memory_mb')),latency_ms:Number(f.get('latency_ms'))};for(const k of ['input_shape','output_shape'])if(f.get(k).trim())constraints[k]=JSON.parse(f.get(k));S.space.global_constraints=constraints;S.space.local_constraints=(S.space.local_constraints||[]).filter((_,i)=>!removed.has(i));if(f.get('left'))S.space.local_constraints.push({left:f.get('left'),operator:f.get('operator'),right:parseScalar(f.get('right'))});await api('/search-space/summary','POST',{ir:S.ir,search_space:S.space});setDirty();$('#modal').close();if(S.page==='search')render();toast('Search constraints saved')});}
async function defaultSpace(){S.space={schema_version:1,variables:[],nodes:{},global_constraints:{max_params:1000000,max_macs:100000000,max_layers:200,max_memory_mb:256},local_constraints:[]};const first=S.ir.nodes.find(n=>n.op==='PatchEmbedding')||S.ir.nodes.find(n=>['ResidualBlock','Conv2d','ConvBlock'].includes(n.op));if(first){const key=first.op==='PatchEmbedding'?'embed_dim':'out_channels';S.space.variables.push({id:'width',node_id:first.id,target:'config.'+key,kind:'discrete',candidate_values:first.op==='PatchEmbedding'?[32,64,96]:[8,16,24,32]});S.space.nodes[first.id]={state:'Searchable'}}const stack=S.ir.nodes.find(n=>n.op==='TransformerStack');if(stack){S.space.variables.push({id:'depth',node_id:stack.id,target:'config.depth',kind:'discrete',candidate_values:[1,2,3]},{id:'heads',node_id:stack.id,target:'config.num_heads',kind:'discrete',candidate_values:[2,4,8]});S.space.nodes[stack.id]={state:'Searchable'}}if(!first&&!stack){const n=S.ir.nodes.find(n=>Object.values(n.config).some(v=>typeof v==='number'));if(n){const key=Object.keys(n.config).find(k=>typeof n.config[k]==='number');S.space.variables.push({id:'parameter',node_id:n.id,target:'config.'+key,kind:'discrete',candidate_values:defaultCandidateValues(n,'config.'+key)});S.space.nodes[n.id]={state:'Searchable'}}}setDirty();await save();render();}
renderSearch=function(){const j=currentSearch(),cs=j?.candidates||[],chosen=cs.find(c=>c.id===S.candidate)||cs[0];$('#page').innerHTML=heading('EXPLORE THE POSSIBILITIES','Search Lab','Find architectures worth training in the space you define.',btn('Space Summary','space-summary','graph')+btn('Compare candidates','compare-candidates','compare')+btn('Train candidate','train-candidate','play',true))+`<div class="page-content"><div class="split-layout"><div class="stack"><div class="panel"><div class="panel-header"><h2>Pareto Explorer</h2><small>Proxy ranking / Model size</small></div><div class="panel-body">${cs.length?scatter(cs,chosen?.id):empty('Start searching from your design','Choose searchable parameters on selected nodes. Other structures stay fixed.',btn('Use default search space','default-space','plus'))}<div class="legend"><span><b></b>Pareto frontier</span><span><b style="background:#bbc9c0"></b>Candidate</span><span style="margin-left:auto">Click to select architecture</span></div></div></div><div class="panel"><div class="panel-header"><h2>Candidate Explorer <small>${cs.length} candidates</small></h2>${j?badge(j.status):''}</div>${j?`<div class="panel-body" style="padding-bottom:0">${jobProgress(j)}</div>`:''}<div class="table-scroll">${cs.length?candidateTable(cs,chosen?.id):empty('Candidates will appear here','Search compiles candidates and executes proxies on the selected device.')}</div></div>${chosen?candidateDetail(chosen,j):''}</div><aside class="stack"><div class="panel"><div class="panel-header"><h2>Your search space</h2><button class="link-button" data-action="edit-space">Edit</button></div><div class="panel-body"><div class="inspector-kv"><span>Variables</span><code>${S.space.variables.length}</code></div><div class="inspector-kv"><span>Searchable nodes</span><code>${new Set(S.space.variables.map(v=>v.node_id)).size}</code></div>${S.space.variables.slice(0,8).map(v=>`<button class="variable-card full-width" data-space-node="${v.node_id}" style="text-align:left"><strong>${esc(v.node_id)} / ${esc(v.target.replace('config.',''))}</strong><small>${esc(v.kind==='range'?v.numeric_range.min+' → '+v.numeric_range.max:JSON.stringify(v.candidate_values||[false,true]))}</small></button>`).join('')}<button class="btn small full-width section-gap" data-action="constraints">${icon('settings')}Search constraints</button></div></div><div class="panel"><div class="panel-header"><h2>New search</h2></div><form id="graph-search-form" class="panel-body"><label class="field"><span>Strategy</span><select name="strategy"><option value="random">Random Search</option><option value="evolution">Evolutionary Search</option></select></label><label class="field"><span>Compute device</span><select name="device">${deviceOptions()}</select></label><div class="form-grid">${field('Candidates','count',S.searchCount||8,'number','min="2" max="256"')}${field('Seed','seed',42,'number','min="0"')}${field('Time budget (s)','budget_seconds',300,'number','min="1" max="86400"')}</div><button class="btn primary full-width" type="submit">${icon('orbit')}Start search</button></form></div>${projectJobs('search').length?`<div class="panel"><div class="panel-header"><h2>Recent searches</h2></div>${projectJobs('search').slice(0,5).map(x=>`<button class="job-card full-width ${x.id===j?.id?'active':''}" data-search-job="${x.id}"><div><strong>${x.candidates.length} candidates</strong><small>${clockTime(x.created_at)} · ${esc(x.device||'cpu')}</small></div>${badge(x.status)}</button>`).join('')}</div>`:''}</aside></div></div>`;
$('#graph-search-form').onsubmit=fire(async e=>{e.preventDefault();if(!S.space.variables.length)throw Error('Add a search variable or use the default space first');const f=new FormData(e.currentTarget);S.runtimeDevice=f.get('device');S.searchCount=Number(f.get('count'));const c=S.space.global_constraints||{};const job=await startTask('search',{ir:rootGraph(),search_space:clone(S.space),strategy:f.get('strategy'),device:f.get('device'),count:Number(f.get('count')),seed:Number(f.get('seed')),budget_seconds:Number(f.get('budget_seconds')),max_params:c.max_params||20000000,max_macs:c.max_macs||2000000000});S.searchJob=job.id;S.candidate=null;render()});bindCandidateEvents(cs);$$('[data-search-job]').forEach(b=>b.onclick=()=>{S.searchJob=b.dataset.searchJob;render()});$$('[data-space-node]').forEach(b=>b.onclick=fire(async()=>{if(S.modulePath.length)await exitModule(0);const parts=b.dataset.spaceNode.split('/');for(const id of parts.slice(0,-1))await enterModule(id);S.selected=parts.at(-1);S.mode='search';S.inspectorTab='search';navigate('architecture')}));};
function geneLabel(id){const v=currentSearch()?.payload.search_space?.variables?.find(v=>v.id===id)||S.space.variables.find(v=>v.id===id);let key=v?.target?.replace('config.','')||id;key=key.replace(/^encoder_/,'');return ({embed_dim:'Dim',hidden_dim:'Dim',out_channels:'Channels',depth:'Depth',num_heads:'Heads',ffn_ratio:'FFN',patch_size:'Patch',repeat:'Repeat',enabled:'Branch',module:'Block'})[key]||key.slice(0,18);}
candidateTable=function(cs,chosen){return `<table><thead><tr><th></th><th>Architecture</th><th>Proxy score</th><th>Params</th><th>MACs</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr class="${c.id===chosen?'selected-row':''}"><td><input type="checkbox" data-compare="${c.id}" ${S.compare.includes(c.id)?'checked':''} aria-label="Compare ${c.id}"></td><td><button class="candidate-name" data-candidate="${c.id}"><span class="rank-no">${String(c.rank).padStart(2,'0')}</span><span><strong>Forge-${c.id.slice(0,6)}</strong><small>${Object.entries(c.genes||{}).slice(0,3).map(([k,v])=>esc(geneLabel(k))+': '+esc(v)).join(' · ')||'Manual architecture'}</small></span></button></td><td class="score">${c.score.toFixed(3)}</td><td class="mono">${compact(c.proxy.params)}</td><td class="mono">${compact(c.proxy.macs)}</td><td>${c.pareto?'<span class="badge green">Pareto</span>':''}</td></tr>`).join('')}</tbody></table>`;};
candidateDetail=function(c,j){return `<div class="panel"><div class="panel-header"><h2>Forge-${c.id.slice(0,6)}</h2><div class="actions"><button class="btn small" data-action="template-diff">${icon('compare')}Compare with template</button><button class="btn small primary" data-action="open-candidate">${icon('check')}Instantiate as new version</button></div></div><div class="panel-body">${proxyMethods(c.proxy)}<div class="actions section-gap"><button class="btn small" data-action="snapshot-candidate">${icon('save')}Save candidate snapshot</button><a class="btn small" href="/api/export/job/${j.id}">${icon('download')}Export records</a></div></div></div>`;};
function proxyMethods(p){return `<div class="method-grid">${['synflow','snip','naswot'].map(k=>{const m=p.methods?.[k];return `<div class="method-card"><h4>${k.toUpperCase()}</h4><div class="value">${p.scores[k]==null?'—':Number(p.scores[k]).toExponential(3)}</div><span class="badge ${m?.status==='unavailable'?'orange':'green'}">${m?.status==='unavailable'?'Unavailable':'Complete'}</span><p>${esc(m?.device||p.device||'cpu')} · ${fmt(m?.seconds||p.method_seconds?.[k],3)}s<br>${m?.memory_peak_mb!=null?'Peak '+fmt(m.memory_peak_mb,1)+' MB':''}${m?.reason?esc(m.reason):''}</p></div>`}).join('')}</div><p class="field-note">Batch ${p.batch_size} · Seed ${p.seed} · ${esc(p.initialization||'PyTorch defaults')} · ${esc(p.device_name||'CPU')}</p>`;}

jobProgress=function(j){return `<div class="run-status ${j.status}"><span class="status-dot"></span><span class="mono" style="font-size:10px">${j.kind==='train'?'Training':j.kind==='search'?'Architecture search':'Proxy analysis'} / ${j.id.slice(0,8)}</span><span style="margin-left:auto">${badge(j.status)}</span></div><div class="progress"><span style="width:${j.progress*100}%"></span></div><div class="run-details"><span>${pct(j.progress)} complete${j.control_pending?' · '+(j.control_pending==='pause'?'Pauses after this epoch':'Stopping task'):''}</span><span>${esc(j.device||'')}</span></div>${j.error?`<div class="error-box">${esc(j.error)}${j.error_context?'<br>'+esc(j.error_context.hint):''}</div>`:''}<div class="actions section-gap">${['running','queued'].includes(j.status)?`${j.kind==='train'?`<button class="btn small" data-control="pause" data-id="${j.id}">${icon('pause')}Pause</button>`:''}<button class="btn small" data-control="cancel" data-id="${j.id}">${icon('stop')}Cancel</button>`:''}${['paused','interrupted','failed'].includes(j.status)&&j.kind==='train'?`<button class="btn small primary" data-control="resume" data-id="${j.id}">${icon('play')}Resume training</button>`:''}${(['completed','failed','cancelled'].includes(j.status)||j.status==='paused'&&j.kind!=='train')?`<button class="btn small" data-control="rerun" data-id="${j.id}">${icon('redo')}Run again</button>`:''}<a class="btn small" href="/api/export/job/${j.id}">${icon('download')}${j.checkpoint?'Export model':'Export records'}</a></div>`;};
function runtimeStrip(j){const last=j?.metrics?.at(-1),mem=j?.memory_current_mb,peak=j?.memory_peak_mb||last?.gpu_memory_mb;return `<div class="runtime-strip"><div class="runtime-item"><small>DEVICE</small><strong>${esc(j?.device||'—')}</strong></div><div class="runtime-item"><small>GPU</small><strong style="font-size:11px">${esc(j?.device_name||'—')}</strong></div><div class="runtime-item"><small>MEMORY / PEAK</small><strong>${mem==null?'—':fmt(mem,0)+' / '+fmt(peak,0)+' MB'}</strong>${mem!=null?`<div class="gpu-meter"><span style="width:${Math.min(100,mem/(j.memory_total_mb||8192)*100)}%"></span></div>`:''}</div><div class="runtime-item"><small>EPOCH / STEP</small><strong>${j?.current_epoch||last?.epoch||0} / ${j?.payload.epochs||0} <code style="font-size:9px;color:#b4c0b8">${j?.current_step?`${j.current_step}/${j.steps_per_epoch}`:''}</code></strong></div><div class="runtime-item"><small>STEP TIME</small><strong>${fmt(j?.step_seconds||last?.step_seconds,3)}s</strong></div><div class="runtime-item"><small>EPOCH TIME</small><strong>${fmt(last?.seconds,2)}s</strong></div><div class="runtime-item"><small>CHECKPOINT</small><strong>${j?.latest_checkpoint_epoch?'Epoch '+j.latest_checkpoint_epoch:j?.checkpoint?'Saved':'—'}</strong></div>${j?.recovered_from_epoch?`<div class="runtime-item"><small>RESTORED</small><strong>Epoch ${j.recovered_from_epoch}</strong></div>`:''}</div>`;}
renderTraining=function(){const j=currentTrain(),ms=j?.metrics||[],last=ms.at(-1);$('#page').innerHTML=heading('BRING YOUR MODEL TO LIFE','Training Studio','Choose a device and start a real training run.',btn('New training','configure-train','play',true))+`<div class="metrics-strip">${metric('VALIDATION ACCURACY',pct(j?.best_val_accuracy),'','','activity')}${metric('TRAINING LOSS',last?fmt(last.train_loss,4):'—','','','layers')}${metric('THROUGHPUT',last?fmt(last.samples_per_second,1):'—','img/s','','activity')}${metric('TEST ACCURACY',pct(j?.test_accuracy),'','','check')}</div><div class="page-content"><div class="split-layout"><div class="stack"><div class="panel"><div class="panel-header"><h2>Active run</h2>${j?badge(j.status):''}</div>${runtimeStrip(j)}<div class="panel-body">${j?jobProgress(j):empty('Ready to train','Start with the current model or a candidate from Search Lab.',btn('Configure training','configure-train','play',true))}</div></div><div class="two-charts"><div class="panel"><div class="panel-header"><h2>Loss</h2></div><div class="panel-body">${lineChart(ms,['train_loss','val_loss'],['Train','Validation'])}</div></div><div class="panel"><div class="panel-header"><h2>Accuracy</h2></div><div class="panel-body">${lineChart(ms,['train_accuracy','val_accuracy'],['Train','Validation'],true)}</div></div></div><div class="panel"><div class="panel-header"><h2>Worker logs</h2><small>${j?.worker_pid?'Process '+j.worker_pid:'Isolated compute process'}</small></div><div class="panel-body job-log">${j?.logs?.map(l=>`<div><span class="muted">${clockTime(l.time)}</span> ${esc(l.text)}</div>`).join('')||'Waiting for task…'}</div></div></div><aside class="stack"><div class="panel"><div class="panel-header"><h2>Configuration</h2></div><div class="panel-body">${j?trainingConfig(j):'<p class="field-note">AdamW / Cosine schedule / Checkpoint</p>'}<div class="section-gap">${btn('New training run','configure-train','plus')}</div></div></div><div class="panel"><div class="panel-header"><h2>Recent runs</h2></div>${projectJobs('train').slice(0,10).map(x=>`<button class="job-card full-width ${x.id===j?.id?'active':''}" data-train-job="${x.id}"><div><strong>${x.payload.source_candidate?'Forge-'+x.payload.source_candidate.slice(0,6):esc(x.payload.ir.name||'Manual model')}</strong><small>${clockTime(x.created_at)} · ${esc(x.device||x.payload.device)} · ${x.metrics.length}/${x.payload.epochs}</small></div>${badge(x.status)}</button>`).join('')}</div></aside></div></div>`;$$('[data-train-job]').forEach(b=>b.onclick=()=>{S.trainJob=b.dataset.trainJob;render()});};
configureTrain=function(candidate=null,sourceJob=null){if(S.modulePath.length)throw Error('Return to the full model before training');const did=sourceJob?.payload.dataset_id||S.project.dataset_id,d=S.datasets.find(x=>x.id===did);modal(candidate?'Train candidate · Forge-'+candidate.id.slice(0,6):'New training run',`<p>${esc(candidate?'Candidate architecture':S.ir.name||'Current model')} · ${esc(d?.name||'No dataset selected')}</p><form id="train-form"><label class="field"><span>Compute device</span><select name="device">${deviceOptions()}</select></label><div class="form-grid">${field('Epochs','epochs',5,'number','min="1" max="200"')}${field('Batch size','batch_size',32,'number','min="2" max="128"')}${field('Learning rate','lr',.001,'number','min="0.000001" max="0.1" step="any"')}${field('Weight decay','weight_decay',.0001,'number','min="0" max="1" step="any"')}${field('Seed','seed',42,'number','min="0"')}</div><details class="section-gap"><summary class="field-note">Training protocol</summary><p class="field-note">AdamW · CosineAnnealingLR · FP32 · Gradient clipping 5 · Checkpoint every epoch</p></details><button class="btn primary full-width section-gap" type="submit">${icon('play')}Start training</button></form>`);$('#train-form').onsubmit=fire(async e=>{e.preventDefault();const p=Object.fromEntries([...new FormData(e.currentTarget)].map(([k,v])=>[k,k==='device'?v:Number(v)]));S.runtimeDevice=p.device;if(candidate)Object.assign(p,{ir:candidate.ir,source_candidate:candidate.id,source_job:sourceJob.id,dataset_id:sourceJob.payload.dataset_id});const j=await startTask('train',p);S.trainJob=j.id;$('#modal').close();navigate('training')});};
function configureProxy(){if(S.modulePath.length)throw Error('Return to the full model before proxy analysis');modal('Proxy analysis',`<form id="proxy-form"><p>${esc(S.ir.name||'Current model')} · SynFlow / SNIP / NASWOT</p><div class="form-grid"><label class="field"><span>Compute device</span><select name="device">${deviceOptions()}</select></label>${field('Seed','seed',42,'number','min="0"')}</div><button class="btn primary full-width" type="submit">${icon('orbit')}Run proxy analysis</button></form>`);$('#proxy-form').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget);S.runtimeDevice=f.get('device');const j=await startTask('proxy',{device:f.get('device'),seed:Number(f.get('seed'))});S.lastProxy=j.id;S.consoleTab='proxy';$('#modal').close();navigate('architecture')});}
function showProxyDetails(){const j=S.jobs.find(j=>j.id===S.lastProxy)||projectJobs('proxy')[0];if(!j){configureProxy();return;}modal('Proxy analysis · '+j.id.slice(0,8),`${jobProgress(j)}${j.candidates[0]?proxyMethods(j.candidates[0].proxy):`<p>${esc(j.logs.at(-1)?.text||'Waiting to run…')}</p>`}`);bindActions();}
const oldRenderConsole=renderConsole;
renderConsole=function(){if(S.consoleTab!=='proxy')return oldRenderConsole();const el=$('#console-lines');if(!el)return;const j=S.jobs.find(j=>j.id===S.lastProxy)||projectJobs('proxy')[0],p=j?.candidates[0]?.proxy;el.textContent=p?`${p.device||'cpu'} · SynFlow ${p.scores.synflow==null?'—':Number(p.scores.synflow).toExponential(3)}   SNIP ${p.scores.snip==null?'—':Number(p.scores.snip).toExponential(3)}   NASWOT ${p.scores.naswot==null?'—':fmt(p.scores.naswot,3)}\n${fmt(p.seconds,3)}s · Batch ${p.batch_size} · ${p.memory_peak_mb!=null?'Peak '+fmt(p.memory_peak_mb,1)+' MB':''}`:j?(j.status+' · '+(j.error||j.logs.at(-1)?.text||'Waiting to compute…')):'Choose Run → Proxy analysis to inspect current proxy signals.';};
const oldRenderDatasets=renderDatasets;
renderDatasets=function(){const d=dataset();if(d?.input_type!=='tokens'){oldRenderDatasets();const actions=$('.page-heading .actions');if(actions){const b=document.createElement('button');b.className='btn';b.textContent='Import token JSON';b.onclick=tokenUploadModal;actions.prepend(b);}return;}$('#page').innerHTML=heading('DATA FOR YOUR NEXT IDEA','Dataset Studio','Start text and sequence classification here.',btn('Import token JSON','token-upload','upload')+btn('Import images','upload-dataset','upload'))+`<div class="page-content"><div class="split-layout"><div class="stack"><div class="panel"><div class="panel-header"><h2>${esc(d.name)}</h2><select id="dataset-select" class="inline-select">${S.datasets.map(x=>`<option value="${x.id}" ${x.id===d.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="panel-body"><div class="stat-inline"><div><small>SAMPLES</small><strong>${d.samples}</strong></div><div><small>SEQUENCE LENGTH</small><strong>${d.shape[0]}</strong></div><div><small>VOCABULARY</small><strong>${d.vocab_size}</strong></div><div><small>CLASSES</small><strong>${d.classes.length}</strong></div></div><div class="section-title" style="margin-top:28px">TOKEN PREVIEW</div><div id="token-preview" class="connected-ports">Loading…</div></div></div><div class="panel"><div class="panel-header"><h2>Class distribution</h2></div><div class="panel-body">${d.classes.map((c,i)=>`<div class="class-row"><span>${esc(c)}</span><div class="bar"><span style="width:${d.counts[i]/Math.max(...d.counts)*100}%"></span></div><code>${d.counts[i]}</code></div>`).join('')}</div></div></div><aside class="stack"><div class="panel"><div class="panel-header"><h2>Dataset version</h2></div><div class="panel-body"><p class="settings-code" style="font-size:10px">${d.id.slice(0,24)}…</p><div class="inspector-kv"><span>Train / Val / Test</span><code>${Object.values(d.split_counts).join(' / ')}</code></div>${btn('Apply to model','apply-dataset','check',true)}<div class="section-gap">${btn('Use Transformer template','token-template','layers')}</div></div></div></aside></div></div>`;$('#dataset-select').onchange=e=>{S.dataset=e.target.value;render()};api('/datasets/'+d.id+'/preview/0').then(v=>{if($('#token-preview'))$('#token-preview').textContent=v.tokens.join(' · ')+'\nLabel: '+v.label});};
const oldApplyDataset=applyDataset;
applyDataset=async function(){const d=dataset();if(!d.input_type){delete S.ir.input_type;delete S.ir.vocab_size;return oldApplyDataset();}history();S.ir.input_shape=d.shape;S.ir.input_type='tokens';S.ir.vocab_size=d.vocab_size;for(const n of S.ir.nodes){if(n.op==='Embedding')n.config.vocab_size=d.vocab_size;}const out=S.ir.nodes.find(n=>n.id===S.ir.output);if(out?.op==='Linear')out.config.out_features=d.classes.length;S.project.dataset_id=d.id;setDirty();await analyze(false);if(S.analysis)await save();render();toast('Token Dataset applied');};
function tokenUploadModal(){modal('Import token classification dataset',`<form id="token-upload-form">${field('Name','name','My token dataset','text','required')}${field('Vocabulary size','vocab_size',128,'number','min="2" max="65536"')}<label class="field"><span>JSON records</span><textarea name="records" required placeholder='[{"tokens":[1,2,3],"label":"class-a"},…]'></textarea></label><p class="field-note">Sequences must have equal length with at least 3 independent samples per class. Token IDs start at 0.</p><button class="btn primary" type="submit">Import & version dataset</button></form>`);$('#token-upload-form').onsubmit=fire(async e=>{e.preventDefault();const f=new FormData(e.currentTarget),d=await api('/datasets/tokens','POST',{name:f.get('name'),vocab_size:Number(f.get('vocab_size')),records:JSON.parse(f.get('records'))});S.datasets=await api('/datasets');S.dataset=d.id;$('#modal').close();navigate('datasets')});}
renderSettings=function(){$('#page').innerHTML=heading('YOUR LOCAL RUNTIME','Runtime','Design, search and train on your own hardware.')+`<div class="page-content"><div class="panel"><div class="panel-header"><h2>Compute devices</h2><span class="badge green">Connected</span></div><div class="panel-body">${(S.system.devices||[]).filter(d=>d.id!=='auto').map(d=>`<div class="runtime-strip" style="padding:15px 0"><span class="document-icon">${icon('chip')}</span><div class="runtime-item"><small>${d.id.toUpperCase()}</small><strong>${esc(d.name)}</strong></div>${d.total_memory_mb?`<div class="runtime-item"><small>MEMORY</small><strong>${fmt(d.total_memory_mb/1024,1)} GB</strong></div>`:''}</div>`).join('')}<div class="section-gap"><div class="inspector-kv"><span>PyTorch</span><code>${esc(S.system.torch)}</code></div><div class="inspector-kv"><span>CUDA runtime</span><code>${esc(S.system.cuda_version||'CPU only')}</code></div><div class="inspector-kv"><span>Worker</span><code>Isolated process per task</code></div><div class="inspector-kv"><span>Version</span><code>${S.system.version}</code></div></div></div></div><details class="section-gap"><summary class="field-note">Runtime directory & technical details</summary><pre class="settings-code">${esc(JSON.stringify(S.system,null,2))}</pre></details></div>`;};
function captureState(){return {ir:clone(S.ir),space:clone(S.space),positions:clone(S.positions),selected:S.selected,selection:[...S.selection]}}
history=function(){S.history.push(captureState());if(S.history.length>50)S.history.shift();S.future=[]};
async function restoreState(value){S.ir=value.ir||value;S.space=value.space||S.space;S.positions=value.positions||{};S.selected=value.selected||S.ir.nodes[0]?.id;S.selection=value.selection||[];setDirty();await analyze(false);render();}
const originalDeleteNode=deleteNode;deleteNode=async function(){await originalDeleteNode();pruneSpace();render()};
versions=async function(){const vs=await api('/projects/'+S.project.id+'/versions');modal('Architecture versions',vs.length?vs.map(v=>`<button class="project-row" data-version="${v.id}"><strong>Revision ${v.revision}</strong><span>${v.ir.nodes.length} blocks · ${v.search_space?.variables?.length||0} search variables · Restore</span></button>`).join(''):'<p>Saving preserves project history.</p>');$$('[data-version]').forEach(b=>b.onclick=fire(async()=>{const v=vs.find(v=>v.id===b.dataset.version);history();S.ir=clone(v.ir);S.space=clone(v.search_space||{schema_version:1,variables:[],nodes:{},global_constraints:{},local_constraints:[]});S.project.dataset_id=v.dataset_id;S.dataset=v.dataset_id;S.positions=clone(v.layout||{});S.modulePath=[];setDirty();await analyze(false);$('#modal').close();navigate('architecture')}))};
Object.assign(ACTIONS,{
 'save':()=>save(),'template':()=>templateModal(),'versions':()=>versions(),'delete-node':()=>deleteNode(),
 'undo':async()=>{if(!S.history.length)return;S.future.push(captureState());await restoreState(S.history.pop())},'redo':async()=>{if(!S.future.length)return;S.history.push(captureState());await restoreState(S.future.pop())},'layout':()=>{history();S.positions={};layoutMissing();setDirty();renderGraph()},
 'go-architecture':()=>navigate('architecture'),'select-all':()=>{S.selection=S.ir.nodes.map(n=>n.id);renderGraph();updateSelectionToolbar()},
 'pack-module':packageModal,'enter-selected-module':()=>enterModule(S.selected),'module-root':()=>exitModule(0),
 'save-module-version':async()=>{const n=S.ir.nodes.find(n=>n.id===S.selected);if(n?.op!=='Module')throw Error('Select a module node');const saved=await api('/modules/import','POST',{name:n.name||'Module',node:n,version:(S.modules.find(m=>m.id===n.library_id)?.version||1)+1,description:'Updated from '+S.project.name});n.library_id=saved.id;S.modules=await api('/modules');setDirty();toast('New module version saved')},
 'import-module':()=>{modal('Import reusable module',`<form id="module-import-form"><label class="field"><span>Module JSON</span><textarea name="json" required placeholder="Paste exported module JSON"></textarea></label><button class="btn primary" type="submit">Import into library</button></form>`);$('#module-import-form').onsubmit=fire(async e=>{e.preventDefault();await api('/modules/import','POST',JSON.parse(new FormData(e.currentTarget).get('json')));S.modules=await api('/modules');$('#modal').close();navigate('modules')})},
 'export-2d':()=>{S.exportMode='2d';navigate('exports')},'export-3d':()=>{S.exportMode='3d';navigate('exports')},'download-svg':()=>downloadDiagram('svg'),'download-png':()=>downloadDiagram('png'),'download-pdf':()=>downloadDiagram('pdf'),
 'add-variable':()=>{const n=S.ir.nodes.find(n=>n.id===S.selected);if(n)variableModal(n)},'space-summary':spaceSummary,'constraints':constraintsModal,'default-space':defaultSpace,
 'edit-space':()=>{S.mode='search';S.inspectorTab='search';navigate('architecture')},
 'proxy':configureProxy,'proxy-details':showProxyDetails,'token-upload':tokenUploadModal,'token-template':()=>useTemplate('transformer'),
 'run-menu':()=>{if(S.modulePath.length)throw Error('Return to the full model first');modal('Run your architecture',`<div class="template-grid"><button class="template-card" id="run-proxy">${icon('orbit')}<strong>Proxy analysis</strong><small>Run SynFlow, SNIP and NASWOT on the selected device.</small></button><button class="template-card" id="run-train">${icon('play')}<strong>Train model</strong><small>Train the current model and save checkpoints automatically.</small></button><button class="template-card" id="run-search">${icon('search')}<strong>Architecture search</strong><small>Explore candidates within the defined local search space.</small></button></div>`);$('#run-proxy').onclick=configureProxy;$('#run-train').onclick=()=>configureTrain();$('#run-search').onclick=()=>{$('#modal').close();navigate('search')}},
 'snapshot-candidate':async()=>{const j=currentSearch(),c=j?.candidates.find(c=>c.id===S.candidate)||j?.candidates[0];if(!c)throw Error('Select a candidate');const p=await api('/projects','POST',{name:'Candidate '+c.id.slice(0,6),ir:c.ir,dataset_id:j.payload.dataset_id});S.projects.unshift(p);toast('Saved as an independent candidate snapshot project')},
 'open-candidate':async()=>{const j=currentSearch(),c=j?.candidates.find(c=>c.id===S.candidate)||j?.candidates[0];if(!c)throw Error('Select a candidate');history();S.ir=clone(c.ir);S.ir.name='Forge-'+c.id.slice(0,6);S.project.dataset_id=j.payload.dataset_id;S.dataset=j.payload.dataset_id;S.space={schema_version:1,variables:[],nodes:{},global_constraints:{},local_constraints:[]};S.modulePath=[];S.positions={};S.selected=S.ir.nodes[0].id;S.mode='design';S.inspectorTab='properties';await analyze(false);setDirty();await save();navigate('architecture');setTimeout(()=>ACTIONS.fit(),20)},
 'template-diff':()=>{const j=currentSearch(),c=j?.candidates.find(c=>c.id===S.candidate)||j?.candidates[0];if(!c)throw Error('Select a candidate');modal('Template → Candidate',`<div class="compare-grid">${[j.payload.ir,c.ir].map((ir,i)=>`<div><h3 style="font-size:13px;color:#8ba394">${i?'Candidate':'Original template'}</h3>${ir.nodes.map(n=>{const other=(i?j.payload.ir:c.ir).nodes.find(o=>o.id===n.id),changed=JSON.stringify(n)!==JSON.stringify(other);return `<div class="diff-row ${changed?'changed':''}"><strong>${esc(n.name||OP_NAMES[n.op]||n.op)}</strong> <span class="muted">${esc(n.id)}</span><br>${esc(JSON.stringify(n.config))}</div>`}).join('')}</div>`).join('')}</div>`)},
 'fit':()=>{const c=$('#canvas');if(!c)return;const ps=Object.values(S.positions),mx=Math.max(...ps.map(p=>p.x))+235,my=Math.max(...ps.map(p=>p.y))+120;S.zoom=Math.min(1,(c.clientWidth-30)/mx,(c.clientHeight-50)/my);S.pan={x:15,y:25};applyTransform()}
});
const originalInit=init;
init=async function(){S.modules=await api('/modules').catch(()=>[]);await originalInit();};
document.body.classList.add('light');localStorage.setItem('nf-theme','light');
$('#help').onclick=()=>modal('A little guidance',`<p><strong>Design</strong><br>Start with a template or add operators individually. Edit parameters by selecting nodes; connect ports to change tensor flow.</p><p><strong>Search</strong><br>Switch to Search Space and add node variables. Configure ranges, discrete choices, conditions, repetition and branches.</p><p><strong>Build blocks</strong><br>Shift Multi-select or Shift-drag, then right-click Create Module. Expand modules, expose parameters and reuse saved versions across projects.</p><p><strong>Share</strong><br>Choose 2D Diagram or 3D Visual to generate SVG, PNG or PDF.</p><p class="field-note">Ctrl+S Save · Ctrl+Z Undo · Ctrl+Y Redo · Delete to remove nodes</p>`);
